SELECT eri.period_id as periodId, eri.report_id as reportId, eri.old_report_id as oldReportId, eri.reason_return as reasonReturn, eri.status as status, eri.period_start_time as periodStartTime, eri.period_end_time as periodEndTime, eri.created_at as createdAt, eri.updated_at as updatedAt, eri.enterprise_nature as enterpriseNature, eri.enterprise_industry as enterpriseIndustry, eri.enterprise_region as enterpriseRegion, ri.construction_count as constructionCount, ri.investigation_count as investigationCount FROM enterprise_report_info eri LEFT JOIN report_info ri ON eri.report_id = ri.report_id
eri.period_id = #{query.periodId}
AND eri.enterprise_region = #{query.enterpriseRegion}
AND eri.status IN
#{item}

select ${groupBy} as code, count(*) as value
FROM enterprise_info
WHERE ${groupBy} IS NOT NULL AND region_code = #{regionCode}
GROUP BY ${groupBy}
ORDER BY value DESC
